function surfaceData(project=p){return surface<project.walls.length?project.walls[surface]:surface===project.walls.length?project.floor:project.ceiling;}
function icon(type){const shapes={sofa:'<rect x="8" y="19" width="64" height="24" rx="5"/><rect x="15" y="8" width="50" height="24" rx="6"/><path d="M8 29h64M17 43v6M63 43v6"/>',bed:'<rect x="15" y="5" width="50" height="44" rx="3"/><rect x="20" y="10" width="18" height="11" rx="2"/><rect x="42" y="10" width="18" height="11" rx="2"/><path d="M15 27h50"/>',desk:'<rect x="8" y="12" width="64" height="12" rx="2"/><path d="M15 24v25M65 24v25M52 24v13h13"/>',wardrobe:'<rect x="17" y="4" width="46" height="45" rx="2"/><path d="M40 4v45M35 23v8M45 23v8"/>'};return `<span class="furniture-icon"><svg viewBox="0 0 80 54" aria-hidden="true"><g fill="#dfe7d3" stroke="currentColor" stroke-width="2.5">${shapes[type]}</g></svg></span>`;}
