function fillFinishes(){fillProducts();const count=p.walls.length;if(surface>count+1)surface=0;const s=surfaceData();$('#surface').innerHTML=[...p.walls.map((_,i)=>`<option value="${i}">Стена ${i+1}</option>`),`<option value="${count}">Пол</option>`,`<option value="${count+1}">Потолок</option>`].join('');$('#surface').value=surface;$('#surface-color').value=s.color;$('#all-walls').hidden=surface>=count;const variants=surface<count?['paint','wallpaper','plaster']:surface===count?['laminate','tile']:['paint','stretch'];$('#finish-options').innerHTML=variants.map(v=>`<button class="finish-card" data-finish="${v}" aria-pressed="${s.finish===v}"><i class="${v}"></i>${LABELS[v]}</button>`).join('');$('#swatches').innerHTML=colours.map(([c,name])=>`<button style="background:${c}" data-color="${c}" aria-label="${name}" title="${name}" aria-pressed="${s.color===c}"></button>`).join('');const materials=surface<count?WALL_MATERIALS:surface===count?FLOOR_MATERIALS:[],selected=materialFor(s,surface===count);$('#material-options').innerHTML=materials.map(m=>`<button data-material="${m.id}" class="material-card" aria-pressed="${selected.id===m.id}"><img src="${sampleURL(m.id,m.color)}" alt="" width="110" height="90"><span>${m.name}</span></button>`).join('');$('#material-note').textContent=surface>count?'Потолок скрыт для обзора. Его отделка сохранится в задании.':`Визуальные образцы, не каталог производителя. Масштаб выбранного образца: ${fmt(selected.rx*100)} × ${fmt(selected.ry*100)} см. Оттенок можно изменить ниже.`;}
