function updateSummary(){const q=quantities(p);$('#project-name').value=p.name;$('#notes').value=p.notes;$('#area').textContent=`${fmt(q.floor)} м²`;$('#project-summary').textContent=`${p.kind} · ${p.shape?.type==='l'?'Г-образная · ':''}${fmt(p.length)} × ${fmt(p.width)} м · высота ${fmt(p.height)} м`;$('#finish-summary').innerHTML=[...p.walls,p.floor,p.ceiling].map((s,i)=>`<div class="finish-row"><i style="background:${s.color}"></i><span>${i<p.walls.length?'Стена '+(i+1):i===p.walls.length?'Пол':'Потолок'} · ${LABELS[s.finish]}${i<=p.walls.length?' · '+materialFor(s,i===p.walls.length).name:''}${productFor(s)?' · '+escape(productFor(s).brand+' '+productFor(s).name+' · '+productFor(s).article):''}</span></div>`).join('');$('#quantities').innerHTML=[['Стены · краска',q.paint,'м²'],['Стены · обои',q.wallpaper,'м²'],['Стены · штукатурка',q.plaster,'м²'],[LABELS[p.floor.finish],q.floor,'м²'],['Потолок',q.ceiling,'м²'],['Плинтус',q.baseboard,'м']].map(([n,a,u])=>`<div class="quantity"><span>${n}</span><b>${fmt(a)} ${u}</b></div>`).join('');$('#preparation').textContent=`Грунтовка стен: предварительно ${fmt(q.total)} м². Демонтаж: ${p.state==='bare'?'не выбран':'объём после осмотра'}.`;$('#whatsapp').href=`https://wa.me/${CONTACT.whatsapp}?text=${encodeURIComponent(specification(p))}`;}
const titles=['Начнём с вашей комнаты','Найдите своё сочетание','Добавьте немного жизни','Ваша идея готова к обсуждению'];
