$('#openings-section').ontoggle=e=>{if(e.target.open){view='plan';if(selectedOpening<0&&p.openings.length)selectedOpening=0;fillOpenings();}updateSteps();draw();};
$('#opening-list').onclick=e=>{const b=e.target.closest('[data-select-opening]');if(b){selectedOpening=+b.dataset.selectOpening;selected=-1;view='plan';fillOpenings();updateSteps();draw();}};
$('#edit-openings').onclick=()=>{view='plan';goStep(0,false);$('#openings-section').open=true;if(selectedOpening<0&&p.openings.length)selectedOpening=0;fillOpenings();updateSteps();draw();};
