$('#openings').onclick=e=>{const b=e.target.closest('[data-delete-opening]');if(b){const next=structuredClone(p);next.openings.splice(+b.dataset.deleteOpening,1);selectedOpening=Math.min(selectedOpening,next.openings.length-1);commit(next);}};
function addOpening(type){if(p.openings.length>=20){feedback('Можно добавить до 20 проёмов.');return;}const next=structuredClone(p);for(let wall=0;wall<p.walls.length;wall++)for(let offset=.1;offset+.9<=wallSegments(p)[wall].length;offset+=.1){next.openings=[...p.openings,{wall,type,offset:+offset.toFixed(2),width:.9,height:type==='door'?Math.min(2.1,p.height):1,sill:type==='door'?0:Math.min(.8,p.height-1),...(type==='door'?{hinge:'start',swing:'in'}:{})}];try{validate(next);selectedOpening=next.openings.length-1;commit(next);return;}catch{}}feedback('Для нового проёма нет места. Уменьшите или переместите существующие.');}
$('#add-window').onclick=()=>addOpening('window');$('#add-door').onclick=()=>addOpening('door');
