$('#surface-color').onchange=e=>{const next=structuredClone(p);surfaceData(next).color=e.target.value;delete surfaceData(next).product;commit(next);};
$('#all-walls').onclick=()=>{if(surface>=p.walls.length)return;const next=structuredClone(p);next.walls=next.walls.map(()=>({...surfaceData()}));commit(next);};
$('#furniture-catalog').onclick=e=>{const b=e.target.closest('[data-add]');if(!b)return;const next=structuredClone(p);try{next.furniture.push(placeFurniture(next,b.dataset.add));}catch(err){feedback(err.message);return;}selected=next.furniture.length-1;view='plan';commit(next);};
$('#furniture-list').onclick=e=>{const b=e.target.closest('[data-select]');if(b){selected=+b.dataset.select;fillFurniture();draw();}};
$('#furniture-editor').onclick=e=>{if(e.target.id==='delete-furniture'){const next=structuredClone(p);next.furniture.splice(selected,1);selected=-1;commit(next);}if(e.target.id==='rotate'){const next=structuredClone(p),f=next.furniture[selected];f.rotation=(f.rotation+90)%360;const {w,d}=footprint(f);if(w>p.length||d>p.width){feedback('После поворота предмет не поместится. Уменьшите его размеры.');return;}f.x=Math.max(0,Math.min(f.x,p.length-w));f.y=Math.max(0,Math.min(f.y,p.width-d));try{next.furniture[selected]=fitRect(next,f);commit(next);}catch(err){feedback(err.message);}}};
$('#furniture-editor').onsubmit=e=>{e.preventDefault();const next=structuredClone(p);e.target.querySelectorAll('[data-field]').forEach(input=>next.furniture[selected][input.dataset.field]=Number(input.value)/100);commit(next);};
$('#view-plan').onclick=()=>{view='plan';updateSteps();draw();};$('#view-3d').onclick=()=>{view='3d';updateSteps();draw();};
function pixel(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};}
function selectHit(hit){if(!hit)return;if(hit.kind==='opening'){selectedOpening=hit.index;selected=-1;goStep(0,false);$('#openings-section').open=true;fillOpenings();updateSteps();draw();return;}selectedOpening=-1;if(hit.kind==='dimensions'){openSizes();return;}if(hit.kind==='resize')return;if(hit.kind==='surface'){surface=hit.index;selected=-1;goStep(1,false);fillFinishes();return;}selected=hit.index;goStep(2,false);fillFurniture();draw();}
canvas.onpointerdown=e=>{
 if(e.button!==0&&e.button!==1)return;
 const px=pixel(e),hit=projection.hitTest(px.x,px.y),wasPlan=view==='plan';
 if(view==='3d'&&(e.button===1||orbitMode||e.pointerType==='touch'||!hit)){e.preventDefault();orbit={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,yaw:camera.yaw,pitch:camera.pitch,hit,tap:e.button===0&&!orbitMode,moved:false};canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing';return;}
 if(e.button!==0)return;
 if(hit?.kind==='resize'){e.preventDefault();resizing={before:structuredClone(p),axis:hit.axis,unproject:projection.unproject};canvas.setPointerCapture(e.pointerId);$('#scene-message').textContent='Меняйте размер перетягиванием. Отпустите, чтобы сохранить.';return;}
 selectHit(hit);
 if(hit?.kind==='opening'&&wasPlan){const pt=projection.unproject(px.x,px.y),o=p.openings[hit.index];openingDrag={before:structuredClone(p),index:hit.index,fraction:Math.max(0,Math.min(1,(projectToWall(wallSegments(p)[o.wall],pt.x,pt.y).t-o.offset)/o.width)),unproject:projection.unproject};canvas.setPointerCapture(e.pointerId);$('#scene-message').textContent='Перетащите проём вдоль стены или к другой стене.';return;}
 if(hit?.kind==='furniture'&&view==='plan'){const pt=projection.unproject(px.x,px.y);drag={dx:pt.x-p.furniture[selected].x,dy:pt.y-p.furniture[selected].y,before:structuredClone(p)};canvas.setPointerCapture(e.pointerId);}
};
canvas.onpointermove=e=>{
 if(orbit){if(Math.hypot(e.clientX-orbit.startX,e.clientY-orbit.startY)>4)orbit.moved=true;camera=cameraState({...camera,yaw:orbit.yaw+(e.clientX-orbit.x)*.45,pitch:orbit.pitch-(e.clientY-orbit.y)*.25});draw();return;}
 const px=pixel(e);
 if(openingDrag){const pt=openingDrag.unproject(px.x,px.y);try{p=moveOpening(openingDrag.before,openingDrag.index,pt.x,pt.y,openingDrag.fraction);const o=p.openings[openingDrag.index];$('#scene-message').textContent=`${o.type==='door'?'Дверь':'Окно'} · стена ${o.wall+1} · отступ ${fmt(o.offset*100)} см`;draw();}catch(err){$('#scene-message').textContent='Здесь разместить нельзя: '+err.message;}return;}
 if(resizing){const pt=resizing.unproject(px.x,px.y),dims={};const bound=n=>Math.round(Math.max(2,Math.min(20,n))*10)/10;if(resizing.axis!=='width')dims.length=bound(pt.x);if(resizing.axis!=='length')dims.width=bound(pt.y);try{p=resizeRoom(resizing.before,dims,true);$('#scene-message').textContent=`${fmt(p.length)} × ${fmt(p.width)} м · ${fmt(floorArea(p))} м²`;draw();}catch(err){$('#scene-message').textContent='Меньше пока нельзя: '+err.message;}return;}
 if(drag){const pt=projection.unproject(px.x,px.y);p.furniture[selected]=moveFurniture(p,selected,pt.x-drag.dx,pt.y-drag.dy);draw();}
};
function endPointer(cancel=false){
 if(orbit){const o=orbit;orbit=null;canvas.style.cursor=orbitMode?'grab':'pointer';if(!cancel&&o.tap&&!o.moved)selectHit(o.hit);return;}
 const pending=openingDrag||resizing||drag;if(!pending)return;const next=structuredClone(p);p=pending.before;resizing=null;drag=null;openingDrag=null;if(cancel){update();}else commit(next);$('#scene-message').textContent='';
}
canvas.onpointerup=()=>endPointer();canvas.onpointercancel=()=>endPointer(true);canvas.onlostpointercapture=()=>{if(orbit||drag||resizing||openingDrag)endPointer(true);};
canvas.addEventListener('mousedown',e=>{if(e.button===1)e.preventDefault();});canvas.addEventListener('auxclick',e=>{if(e.button===1)e.preventDefault();});
canvas.addEventListener('wheel',e=>{if(e.ctrlKey)return;e.preventDefault();camera=cameraState({...camera,zoom:camera.zoom*Math.exp(-e.deltaY*.001)});draw();},{passive:false});
function syncCamera(){const cam=cameraState(camera);$('#camera-state').textContent=`${Math.round(cam.zoom*100)}%`;$('#camera-state').title=`Поворот ${Math.round(cam.yaw)}°, наклон ${Math.round(cam.pitch)}°`;$('#camera-tools').hidden=view!=='3d';$('#orbit-mode').setAttribute('aria-pressed',String(orbitMode));canvas.style.cursor=orbit?'grabbing':orbitMode&&view==='3d'?'grab':'pointer';}
$('#orbit-mode').onclick=()=>{orbitMode=!orbitMode;syncCamera();};
for(const [id,field,amount] of [['#turn-left','yaw',-30],['#turn-right','yaw',30],['#tilt-up','pitch',10],['#tilt-down','pitch',-10],['#zoom-in','zoom',.15],['#zoom-out','zoom',-.15]])$(id).onclick=()=>{camera=cameraState({...camera,[field]:camera[field]+amount});draw();};
$('#camera-reset').onclick=()=>{camera={...DEFAULT_CAMERA};draw();};
for(const b of $$('.camera-toolbar button[aria-label]'))b.title=b.getAttribute('aria-label');
function openSizes(){for(const k of ['length','width','height']){$('#size-'+k).value=p[k];$('#range-'+k).value=p[k];}$('#size-error').textContent='';$('#size-dialog').showModal();}
$('#edit-size').onclick=openSizes;$('#resize-plan').onclick=()=>{if(p.shape?.type==='l'){goStep(0,false);$('#shape-form').scrollIntoView({block:'center'});return;}$('#openings-section').open=false;selectedOpening=-1;view='plan';camera.zoom=1;goStep(0,false);$('#scene-message').textContent='Тяните зелёные маркеры: справа — длина, снизу — ширина, угол — оба размера.';};
for(const k of ['length','width','height']){$('#range-'+k).oninput=e=>{$('#size-'+k).value=e.target.value;};$('#size-'+k).oninput=e=>{$('#range-'+k).value=e.target.value;};}
$('#size-form').onsubmit=e=>{e.preventDefault();try{const dims={};for(const k of ['length','width','height'])dims[k]=Number($('#size-'+k).value);const next=resizeRoom(p,dims,$('#adapt-room').checked);if(commit(next))$('#size-dialog').close();}catch(err){$('#size-error').textContent='Не удалось изменить размер: '+err.message;}};
$('#warnings').onclick=e=>{const b=e.target.closest('[data-warning]');if(b){selected=warnings(p)[+b.dataset.warning].indices[0];goStep(2);fillFurniture();draw();}};
$('#undo').onclick=()=>{p=timeline.undo();selected=-1;feedback('');save();update();};$('#redo').onclick=()=>{p=timeline.redo();selected=-1;feedback('');save();update();};
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('#redo'):$('#undo')).click();}});
for(const [id,prop] of [['#project-name','name'],['#notes','notes']])$(id).oninput=e=>{const next=structuredClone(p);next[prop]=e.target.value;timeline.set(next);p=timeline.current;save();$('#whatsapp').href=`https://wa.me/${CONTACT.whatsapp}?text=${encodeURIComponent(specification(p))}`;updateSteps();};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').onclick=()=>download(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}),'TED-room.json');
$('#spec').onclick=()=>download(new Blob(['\ufeff'+specification(p)],{type:'text/plain;charset=utf-8'}),'TED-room-specification.txt');
$('#png').onclick=()=>canvas.toBlob(blob=>{if(blob)download(blob,'TED-room.png');else feedback('Не удалось сохранить изображение.');});
$('#files-open').onclick=()=>$('#files-dialog').showModal();$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());
$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;$('#files-dialog').close();try{if(f.size>200000)throw Error('Файл слишком большой: максимум 200 КБ.');const next=validate(JSON.parse(await f.text()));if(await ask('Открыть сохранённый проект?')){selected=-1;if(commit(next))feedback('Проект открыт. Можно продолжать редактирование.');}}catch{feedback('Не удалось открыть файл. Выберите файл проекта TED в формате JSON (до 200 КБ). Текущая комната сохранена.');}e.target.value='';};
$('#reset').onclick=async()=>{$('#files-dialog').close();if(await ask('Начать новую комнату?')){selected=-1;step=0;view='3d';commit(template('Гостиная'));}};
$('#back-scene').onclick=()=>$('.scene-panel').scrollIntoView({block:'start',behavior:'smooth'});
function applyShape(shape){try{const next=reshapeRoom(p,shape);surface=0;selectedOpening=-1;selected=-1;view='plan';commit(next);}catch(err){feedback(err.message);}}
$$('[data-shape]').forEach(b=>b.onclick=()=>applyShape(b.dataset.shape==='l'?{type:'l',corner:'se',cutWidth:Math.max(.5,Math.round(p.length*.4*100)/100),cutDepth:Math.max(.5,Math.round(p.width*.4*100)/100)}:{type:'rectangle'}));
$('#shape-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements;applyShape({type:'l',corner:f.namedItem('corner').value,cutWidth:Number(f.namedItem('cutWidth').value),cutDepth:Number(f.namedItem('cutDepth').value)});};
$('#material-options').onclick=e=>{const b=e.target.closest('[data-material]');if(!b)return;const m=[...WALL_MATERIALS,...FLOOR_MATERIALS].find(v=>v.id===b.dataset.material);const next=structuredClone(p);delete surfaceData(next).product;Object.assign(surfaceData(next),{finish:m.finish,texture:m.id,color:m.color});commit(next);};


function fillProducts(){if(surface>p.walls.length+1)surface=0;const target=surface<p.walls.length?'wall':surface===p.walls.length?'floor':'ceiling',current=productFor(surfaceData());$('#product-catalog').hidden=target==='ceiling';$('#product-options').innerHTML=PRODUCTS.filter(v=>v.target===target).map(v=>`<article class="product-card"><strong>${v.brand} · ${v.name}</strong><small>Артикул ${v.article}</small><p>${v.details}</p><a href="${v.url}" target="_blank" rel="noopener noreferrer">Фото и описание производителя ↗</a><button data-product="${v.id}" aria-pressed="${current?.id===v.id}">${current?.id===v.id?'✓ Выбран':'Выбрать для этой поверхности'}</button></article>`).join('');$('#chosen-product').textContent=current?`В задании: ${current.brand} ${current.name}, арт. ${current.article}. Цвет и фактура приблизительные. Смена цвета или образца снимет привязку к товару.`:'';}
$('#product-options').onclick=e=>{const b=e.target.closest('[data-product]');if(!b)return;const next=structuredClone(p);Object.assign(surfaceData(next),applyProduct(surfaceData(next),b.dataset.product,surface<p.walls.length?'wall':'floor'));commit(next);};
let compareSlots=[null,null],compareError='';const compareKey='ted-comparison-v1';
try{const raw=localStorage.getItem(compareKey);if(raw)compareSlots=readComparison(JSON.parse(raw));}catch{compareError='Не удалось восстановить сравнение. Текущая комната доступна; откройте скачанный файл сравнения.';}
function persistComparison(){try{localStorage.setItem(compareKey,JSON.stringify(comparisonFile(compareSlots)));return true;}catch{$('#compare-status').textContent='Не удалось сохранить варианты на устройстве. Скачайте оба варианта файлом.';return false;}}
function fillComparison(){const labels=['А','Б'];$('#compare-grid').innerHTML=compareSlots.map((s,i)=>`<section class="compare-card"><h3>Вариант ${labels[i]}</h3>${s?`<canvas width="800" height="600" data-compare-canvas="${i}" aria-label="Вариант ${labels[i]}: изображение комнаты"></canvas><strong>${escape(s.name)}</strong><p>${s.shape?.type==='l'?'Г-образная':'Прямоугольная'} · ${fmt(quantities(s).floor)} м² · ${fmt(s.length)} × ${fmt(s.width)} м</p><p class="hint">Бюджет: ${s.budget?fmt(budgetSummary(s).total)+' ₸ · не оценено: '+budgetSummary(s).missing:'цены не внесены'}</p><details><summary>Отделка варианта ${labels[i]}</summary>${[...s.walls,s.floor,s.ceiling].map((v,n)=>`<p class="compare-finish"><i style="background:${v.color}"></i>${n<s.walls.length?'Стена '+(n+1):n===s.walls.length?'Пол':'Потолок'}: ${LABELS[v.finish]} · ${v.color}${productFor(v)?' · '+escape(productFor(v).brand+' '+productFor(v).name+' '+productFor(v).article):n<=s.walls.length?' · '+materialFor(v,n===s.walls.length).name:''}</p>`).join('')}</details><button data-compare-use="${i}" class="wide">Редактировать вариант ${labels[i]}</button>`:'<div class="compare-empty">Сохраните сюда текущую комнату</div>'}<button data-compare-save="${i}" class="wide secondary">${s?'Обновить':'Сохранить'} ${labels[i]} из текущей комнаты</button></section>`).join('');compareSlots.forEach((s,i)=>{if(s)render($(`[data-compare-canvas="${i}"]`),s,'3d',-1,-1,[],{...camera,zoom:1});});$('#compare-export').disabled=!compareSlots.some(Boolean);}
$('#compare-open').onclick=()=>{fillComparison();$('#compare-status').textContent=compareError;$('#compare-dialog').showModal();};
$('#compare-grid').onclick=async e=>{const saveButton=e.target.closest('[data-compare-save]'),useButton=e.target.closest('[data-compare-use]');if(saveButton){const i=+saveButton.dataset.compareSave;if(compareSlots[i]&&!await ask('Обновить вариант '+['А','Б'][i]+'?','Старый снимок в этом слоте заменится текущей комнатой. Чтобы оставить копию, сначала скачайте оба варианта.'))return;compareSlots[i]=structuredClone(p);fillComparison();if(persistComparison())$('#compare-status').textContent='Вариант '+['А','Б'][i]+' сохранён. Закройте сравнение, чтобы изменить комнату.';}if(useButton){const next=structuredClone(compareSlots[+useButton.dataset.compareUse]);surface=0;selected=-1;selectedOpening=-1;if(commit(next)){$('#compare-dialog').close();feedback('Вариант открыт для редактирования. Предыдущую комнату можно вернуть кнопкой отмены.');}}};
$('#compare-export').onclick=()=>download(new Blob([JSON.stringify(comparisonFile(compareSlots),null,2)],{type:'application/json'}),'TED-comparison.json');
$('#compare-import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>400000)throw Error();const slots=readComparison(JSON.parse(await f.text()));if(await ask('Открыть два варианта из файла?','Слоты А и Б будут заменены. Текущая комната в редакторе останется.')){compareSlots=slots;compareError='';fillComparison();if(persistComparison())$('#compare-status').textContent='Сравнение загружено.';}}catch{$('#compare-status').textContent='Не удалось открыть сравнение. Нужен файл TED-comparison.json до 400 КБ. Существующие варианты сохранены.';}e.target.value='';};
function fillShopping(){$('#material-reserve').value=p.materialPlan?.reserve??10;$('#shopping-list').innerHTML=materialRows(p).map(r=>`<article class="shopping-item"><small>${escape(r.where)}</small><h3>${escape(r.name)}</h3><strong>${escape(r.amount)}</strong><p>${escape(r.note)}</p>${r.url?`<a href="${r.url}" target="_blank" rel="noopener noreferrer">Параметры производителя ↗</a>`:''}</article>`).join('');}
