$('#shopping-export').onclick=()=>download(new Blob(['\ufeff'+p.name+'\n\n'+materialListText(p)],{type:'text/plain;charset=utf-8'}),'TED-materials.txt');
function fillBudget(){const b=budgetSummary(p);$('#budget-rows').innerHTML=['Материалы','Работы'].map(category=>`<h3>${category}</h3>${b.rows.filter(r=>r.category===category).map(r=>`<div class="budget-row"><div><strong>${escape(r.name)}</strong><p class="hint">${escape(r.detail)} · количество: ${fmt(r.quantity)} ${escape(r.unit)}</p></div><label>Цена, ₸ / ${escape(r.unit)}<input data-budget-id="${escape(r.id)}" type="number" min="0" max="1000000000" step="0.01" value="${r.price??''}" placeholder="Не указана"></label><output>${r.total===null?'Не оценено':fmt(r.total)+' ₸'}</output></div>`).join('')}`).join('');$('#budget-totals').innerHTML=`<span>Материалы: ${fmt(b.materials)} ₸ · Работы: ${fmt(b.work)} ₸</span><strong>${b.missing?'Учтено':'Итого'}: ${fmt(b.total)} ₸</strong><span>${b.missing?'Ещё не оценено позиций: '+b.missing:'Все показанные позиции оценены. Состав ремонта уточняется после замера.'}</span>`;}
$('#budget-open').onclick=()=>{fillBudget();$('#budget-status').textContent='';$('#budget-dialog').showModal();};
