$('#budget-form').onsubmit=e=>{e.preventDefault();const next=structuredClone(p),prices={};$('#budget-rows').querySelectorAll('[data-budget-id]').forEach(input=>{if(input.value!=='')prices[input.dataset.budgetId]=Number(input.value);});next.budget={prices};if(commit(next))$('#budget-status').textContent='Цены сохранены. Объёмы пересчитаются при изменении комнаты.';};
$('#budget-export').onclick=()=>{if($('#budget-status').textContent.startsWith('Есть несохранённые')){$('#budget-status').textContent='Есть несохранённые цены. Сначала сохраните их, чтобы скачать актуальный бюджет.';return;}download(new Blob(['\ufeff'+p.name+'\n\n'+budgetText(p)],{type:'text/plain;charset=utf-8'}),'TED-budget.txt');};
